#[path="/Users/nk/Desktop/ducksmiles-analytics-20261021/crates/analytics/src/distributions.rs"] mod distributions;
#[path="/Users/nk/Desktop/ducksmiles-analytics-20261021/crates/analytics/src/arima.rs"] mod arima;
fn main() {
 let v:Vec<String>=std::env::args().collect();
 let data:Vec<Vec<f64>>=v[2].split(';').map(|r|r.split(',').map(|x|x.parse().unwrap()).collect()).collect();
 let args:Vec<f64>=if v[3].is_empty(){vec![]}else{v[3].split(',').map(|x|x.parse().unwrap()).collect()};
 let out=if v[1]=="arima"{arima::run(&v[1],&data,&args)}else{distributions::run(&v[1],&data,&args)};
 match out {Ok(s)=>println!("{}",s),Err(e)=>{eprintln!("{}",e);std::process::exit(2);}}
}
